async function guardedShapeConfirmationArgs(
  paths: NativeProjectPaths,
  name: string,
  summary: string,
): Promise<string[]> {
  const state = await readNativePortableChange(paths, name);
  return [
    name,
    '--summary',
    summary,
    '--confirmed',
    '--expected-state-version',
    String(state.state_version),
    '--expected-action',
    'confirm-shape',
  ];
}

